/*
 * Glossary of the worklist and reading screens: every word they show, in English and Korean (worklist-language.js).
 * terms: [the words as the page writes them, the other language, kind, (optional) the same language with translated
 *   button names]. kind: l label, m sentence, s server error; c marks a control that changes a report or a study.
 *   {0} data shown as is, {t0} words the code chose, {e0} an error message; each translation keeps the same slots.
 * css: [screen, selector, English, Korean] for words in CSS content.
 * skip: words found in the code that the screen never shows as words to translate (code values, sample data).
 * A new word on these screens is added here; tests/worklist_language_source_test.py names any that is missing.
 */
